SELECT id, service, host, latency_ms, status_code, context['trace'] AS trace, GET_JSON_OBJECT(payload_json, '$.user.id') AS user_id, context['version'] AS version, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').user.tier AS tier FROM app_logs
